import { createRoute, z } from '@hono/zod-openapi'

const CartingPlatformTypeSchema = z
  .int()
  .min(1)
  .max(2)
  .openapi({ description: 'The vendor platform type of the carting ad. 1 for MIKMAK, 2 for PEAR.' })
  .openapi('CartingPlatformType')

const CartingRetailerSchema = z
  .object({
    retailer_id: z.string().openapi({ description: 'Unique identifier for the retailer' }),
    retailer_name: z.string().openapi({ description: 'Name of the retailer' }),
  })
  .openapi({ required: ['retailer_id', 'retailer_name'] })
  .openapi('CartingRetailer')

const CartingProductSchema = z
  .object({
    carting_product_id: z
      .string()
      .regex(/^\d+$/)
      .openapi({
        description:
          'the internal Pinterest carting product id (different from industry product id)',
      }),
    display_preferred_retailers_only: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Whether to display only the preferred retailers for the carting product',
      }),
    display_product_price: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether to display the price for the carting product' }),
    preferred_retailers: z
      .array(CartingRetailerSchema)
      .exactOptional()
      .openapi({ description: 'A sorted array of preferred retailers for the carting product' }),
    randomize_preferred_retailers: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether to randomize preferred retailers for the carting product' }),
  })
  .openapi({ required: ['carting_product_id'] })
  .openapi('CartingProduct')

const AdCollectionsHeaderTypeSchema = z
  .union([
    z.literal('SHOP_THIS_COLLECTION'),
    z.literal('EXPLORE_THIS_COLLECTION'),
    z.literal('NO_HEADER'),
    z.literal(null),
  ])
  .nullable()
  .openapi({ description: 'Collections ad header type for ads', example: 'SHOP_THIS_COLLECTION' })
  .openapi('AdCollectionsHeaderType')

const CreativeTypeSchema = z
  .enum([
    'REGULAR',
    'VIDEO',
    'SHOPPING',
    'CAROUSEL',
    'MAX_VIDEO',
    'SHOP_THE_PIN',
    'COLLECTION',
    'IDEA',
    'SHOWCASE',
    'QUIZ',
    'COLLAGE',
    'MAX_WIDTH_REGULAR_COLLECTION',
    'MAX_WIDTH_VIDEO_COLLECTION',
    'APP',
  ])
  .openapi({
    description:
      'Ad creative type enum.\n**Note:** SHOP_THE_PIN has been deprecated. Please use COLLECTION instead.',
    title: 'CreativeType enum used ads',
  })
  .openapi('CreativeType')

const CustomizableCTATypeSchema = z
  .union([
    z.literal('GET_OFFER'),
    z.literal('LEARN_MORE'),
    z.literal('ORDER_NOW'),
    z.literal('SHOP_NOW'),
    z.literal('SIGN_UP'),
    z.literal('SUBSCRIBE'),
    z.literal('BUY_NOW'),
    z.literal('CONTACT_US'),
    z.literal('GET_QUOTE'),
    z.literal('VISIT_SITE'),
    z.literal('APPLY_NOW'),
    z.literal('BOOK_NOW'),
    z.literal('REQUEST_DEMO'),
    z.literal('REGISTER_NOW'),
    z.literal('FIND_A_DEALER'),
    z.literal('ADD_TO_CART'),
    z.literal('WATCH_NOW'),
    z.literal('READ_MORE'),
    z.literal('BUY_TICKETS'),
    z.literal('DONATE_NOW'),
    z.literal('DOWNLOAD'),
    z.literal('EXPLORE_MORE'),
    z.literal('FIND_A_LOCATION'),
    z.literal('FIND_RETAILERS'),
    z.literal('GET_DEAL'),
    z.literal('GET_RECIPE'),
    z.literal('GET_SHOWTIMES'),
    z.literal('ON_SALE'),
    z.literal('PLAY_GAME'),
    z.literal('TRY_IT'),
    z.literal('TAKE_A_PEEK'),
    z.literal(null),
  ])
  .nullable()
  .openapi({
    description:
      'Select a call to action (CTA) to display below your ad. Available only for ads with direct links enabled. CTA options for consideration and conversion campaigns are LEARN_MORE, SHOP_NOW, BOOK_NOW, SIGN_UP, VISIT_SITE, BUY_NOW, GET_OFFER, ORDER_NOW, ADD_TO_CART (for conversion campaigns with add to cart conversion events only)',
    example: 'LEARN_MORE',
  })
  .openapi('CustomizableCTAType')

const DisclosureTypeSchema = z
  .union([
    z.literal('NO_DISCLOSURE'),
    z.literal('PRESCRIBING_INFORMATION'),
    z.literal('PRESCRIBING_INFORMATION_BOX_WARNING'),
    z.literal('IMPORTANT_SAFETY_INFO'),
    z.literal('MED_GUIDE'),
    z.literal('PATIENT_INFORMATION'),
    z.literal(null),
  ])
  .nullable()
  .openapi({
    description:
      'Type of information in the page referenced by `disclosure_url`, provided either by the Food and Drug Administration (FDA) or the manufacturer.',
    example: 'MED_GUIDE',
  })
  .openapi('DisclosureType')

const GridClickTypeSchema = z
  .enum(['CLOSEUP', 'DIRECT_TO_DESTINATION'])
  .nullable()
  .openapi({
    description:
      'Where a user is taken after clicking on an ad in grid.\n\n**Note:**  This parameter is read-only and is set to `DIRECT_TO_DESTINATION` by default for direct links supported ads. `grid_click_type` values provided will be ignored.',
    example: 'CLOSEUP',
  })
  .openapi('GridClickType')

const QuizPinOptionSchema = z
  .object({ id: z.number().exactOptional(), text: z.string().exactOptional() })
  .nullable()
  .openapi({
    description: 'This field contains multiple options to a quiz question.',
    example: { id: 1, text: 'Where do you thrive?' },
    required: [],
  })
  .openapi('QuizPinOption')

const QuizPinQuestionSchema = z
  .object({
    options: z.array(QuizPinOptionSchema).exactOptional(),
    question_id: z.number().exactOptional(),
    question_text: z.string().exactOptional(),
  })
  .nullable()
  .openapi({
    description: 'A specific quiz inquiry.',
    example: {
      question_id: 1,
      question_text: 'Where do you thrive?',
      options: [
        { text: 'Hangout vibes' },
        { text: 'Time to party!' },
        { text: 'Keeping it lowkey' },
      ],
    },
    required: [],
  })
  .openapi('QuizPinQuestion')

const QuizPinResultSchema = z
  .object({
    android_deep_link: z.string().exactOptional(),
    destination_url: z.string().exactOptional(),
    ios_deep_link: z.string().exactOptional(),
    organic_pin_id: z.string().exactOptional(),
    result_id: z.number().exactOptional(),
  })
  .nullable()
  .openapi({
    description: 'The result, and link out, based on the user’s choice.',
    example: {
      organic_pin_id: 'pinId',
      android_deep_link: 'https://www.pinterest.com/',
      ios_deep_link: 'https://www.pinterest.com/',
      destination_url: 'https://www.pinterest.com/',
    },
    required: [],
  })
  .openapi('QuizPinResult')

const TieBreakerTypeSchema = z
  .enum(['RANDOM', 'CUSTOM'])
  .openapi({ description: 'Quiz ad tie breaker type, default is RANDOM' })
  .openapi('TieBreakerType')

const QuizPinDataSchema = z
  .object({
    questions: z.array(QuizPinQuestionSchema).exactOptional(),
    results: z.array(QuizPinResultSchema).exactOptional(),
    tie_breaker_custom_result: QuizPinResultSchema.exactOptional(),
    tie_breaker_type: TieBreakerTypeSchema.exactOptional(),
  })
  .nullable()
  .openapi({
    description: 'This field includes all quiz data including questions, options, and results.',
    example: {
      questions: [
        {
          question_id: 1,
          question_text: 'Where do you thrive?',
          options: [
            { text: 'Hangout vibes' },
            { text: 'Time to party!' },
            { text: 'Keeping it lowkey' },
          ],
        },
        {
          question_id: 2,
          question_text: 'Where would you nap?',
          options: [
            { text: 'Hammock in the mountains' },
            { text: 'Beach towel in the sand' },
            { text: 'Tent under the stars' },
          ],
        },
        {
          question_id: 2,
          question_text: 'Who are you taking?',
          options: [
            { text: 'No one—solo trip!' },
            { text: 'My best friend' },
            { text: 'The family' },
          ],
        },
      ],
      results: [
        {
          organicPinId: '1234',
          android_deep_link: 'https://www.pinterest.com/',
          iOS_deep_link: 'https://www.pinterest.com/',
          destination_url: 'https://www.pinterest.com/',
          result_id: 1,
        },
        {
          organicPinId: '1234',
          android_deep_link: 'https://www.pinterest.com/',
          iOS_deep_link: 'https://www.pinterest.com/',
          destination_url: 'https://www.pinterest.com/',
          result_id: 2,
        },
        {
          organicPinId: '1234',
          android_deep_link: 'https://www.pinterest.com/',
          iOS_deep_link: 'https://www.pinterest.com/',
          destination_url: 'https://www.pinterest.com/',
          result_id: 3,
        },
      ],
    },
    required: [],
  })
  .openapi('QuizPinData')

