    'SHOCKING',
    'WEIGHT_LOSS',
    'PROHIBITED_PRODUCT',
    'AUTHENTICITY',
    'NUDITY',
    'CONFUSING_DESIGN',
    'URGENCY',
    'RATINGS',
    'APP',
    'ALCOHOL',
    'CONTESTS',
    'POLITICAL',
    'OTHER',
    'IMAGE',
    'NAR',
    'INCONSISTENT',
    'CLICKBAIT',
    'NO_DESCRIPTION',
    'LOW_QUALITY',
    'EXAGGERATED_CLAIMS',
    'PINTEREST_BRAND',
    'ALCOHOL_NO_SALE',
    'LANDING_PAGE_SPEED',
    'LANDING_PAGE_HARDWALL',
    'LANDING_PAGE_BROKEN',
