const AiDisclosuresSchema = z
  .object({
    values: z
      .array(AiDisclosureItemSchema)
      .openapi({
        description: 'List of AI disclosure declarations the creator has made about this Pin.',
      }),
  })
  .openapi({
    description: 'AI disclosure declarations the creator has made about the Pin.',
    required: ['values'],
  })
  .openapi('AiDisclosures')

const BoardOwnerSchema = z
  .object({ username: z.string().exactOptional().openapi({ readOnly: true }) })
  .openapi({ title: 'Board owner containing the username.', required: [] })
  .openapi('BoardOwner')

const ImageDetailsSchema = z
  .object({ height: z.int().nullable(), url: z.string(), width: z.int().nullable() })
  .openapi({
    required: ['height', 'url', 'width'],
    title: 'Image details containing the URL and dimensions.',
  })
  .openapi('ImageDetails')

const ImageSizeSchema = z
  .object({
    '1200x': ImageDetailsSchema.exactOptional(),
    '150x150': ImageDetailsSchema.exactOptional(),
    '400x300': ImageDetailsSchema.exactOptional(),
    '600x': ImageDetailsSchema.exactOptional(),
  })
  .openapi({
    example: {
      '150x150': {
        width: 150,
        height: 150,
        url: 'https://i.pinimg.com/150x150/0d/f6/f1/0df6f1f0bfe7aaca849c1bbc3607a34b.jpg',
      },
      '400x300': {
        width: 400,
        height: 300,
        url: 'https://i.pinimg.com/400x300/0d/f6/f1/0df6f1f0bfe7aaca849c1bbc3607a34b.jpg',
      },
      '600x': {
        width: 600,
        height: 600,
        url: 'https://i.pinimg.com/600x/0d/f6/f1/0df6f1f0bfe7aaca849c1bbc3607a34b.jpg',
      },
      '1200x': {
        width: 1200,
        height: 1200,
        url: 'https://i.pinimg.com/1200x/0d/f6/f1/0df6f1f0bfe7aaca849c1bbc3607a34b.jpg',
      },
    },
    required: [],
  })
  .openapi('ImageSize')

const PinMediaWithImageSchema = z
  .object({ images: ImageSizeSchema.exactOptional(), media_type: z.literal('image') })
  .openapi({
    description: 'Pin with image.',
    required: ['media_type'],
    title: 'Object containing image definitions.',
  })
  .openapi('PinMediaWithImage')

const PinMediaWithVideoSchema = z
  .object({
    cover_image_url: z.string().exactOptional(),
    duration: z
      .number()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Duration (in miliseconds). Field maybe null after creation due to video processing time.',
      }),
    height: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Height (in pixels). Field maybe null after creation due to video processing time.',
      }),
    images: ImageSizeSchema.exactOptional(),
    media_type: z.literal('video'),
    video_url: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Video url (720p).\n\n**Note:** This field is limited and not available to all apps.',
      }),
    video_url_hls: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Video url (HLS).\n\n**Note:** This field is limited and not available to all apps.',
      }),
    width: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Width (in pixels). Field maybe null after creation due to video processing time.',
      }),
  })
  .openapi({
    description: 'Pin with video.',
    required: ['media_type'],
    title: 'Object containing video definitions.',
  })
  .openapi('PinMediaWithVideo')

const ImageMetadataSchema = z
  .object({
    description: z.string().nullable().exactOptional(),
    images: ImageSizeSchema.exactOptional(),
    item_type: z
      .literal('image')
      .openapi({
        description:
          'Discriminator literal identifying this as image metadata inside a `PinMediaMetadata` payload.',
      }),
    link: z.string().nullable().exactOptional(),
    title: z.string().nullable().exactOptional(),
  })
  .openapi({
    required: ['item_type'],
    title: 'Image metadata containing the description, images, item type, link, and title.',
  })
  .openapi('ImageMetadata')

const PinMediaWithImagesSchema = z
  .object({
    items: z.array(ImageMetadataSchema).exactOptional(),
    media_type: z.literal('multiple_images'),
  })
  .openapi({
    description: 'Pin with multiple images.',
    required: ['media_type'],
    title: 'Object containing images definitions.',
  })
  .openapi('PinMediaWithImages')

const VideoMetadataWithItemTypeSchema = z
  .object({
    cover_image_url: z.string().exactOptional(),
    duration: z
      .number()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Duration (in miliseconds). Field maybe null after creation due to video processing time.',
      }),
    height: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Height (in pixels). Field maybe null after creation due to video processing time.',
      }),
    item_type: z
      .literal('video')
      .openapi({
        description:
          'Discriminator literal identifying this as video metadata inside a `PinMediaMetadata` payload.',
      }),
    video_url: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Video url (720p).\n\n**Note:** This field is limited and not available to all apps.',
      }),
    video_url_hls: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Video url (HLS).\n\n**Note:** This field is limited and not available to all apps.',
      }),
    width: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Width (in pixels). Field maybe null after creation due to video processing time.',
      }),
  })
  .openapi({
    required: ['item_type'],
    title: 'Video metadata with required itemType discriminator.',
  })
  .openapi('VideoMetadataWithItemType')

const PinMediaWithVideosSchema = z
  .object({
    items: z.array(VideoMetadataWithItemTypeSchema).exactOptional(),
    media_type: z.literal('multiple_videos'),
  })
  .openapi({
    description: 'Pin with multiple videos.',
    required: ['media_type'],
    title: 'Object containing videos definitions.',
  })
  .openapi('PinMediaWithVideos')

const PinMediaMetadataSchema = z
  .discriminatedUnion('item_type', [ImageMetadataSchema, VideoMetadataWithItemTypeSchema])
  .openapi({
    description:
      'Per-item entry inside `PinMedia.items` for mixed image/video pins. Discriminated by `item_type`.',
    discriminator: {
      propertyName: 'item_type',
      mapping: {
        image: '#/components/schemas/ImageMetadata',
        video: '#/components/schemas/VideoMetadataWithItemType',
      },
    },
  })
  .openapi('PinMediaMetadata')

const PinMediaWithImageAndVideoSchema = z
  .object({
    items: z.array(PinMediaMetadataSchema).exactOptional(),
    media_type: z.literal('multiple_mixed'),
  })
  .openapi({
    description: 'Pin with a mix of images and videos.',
    required: ['media_type'],
    title: 'Object containing video and image definitions.',
  })
  .openapi('PinMediaWithImageAndVideo')

const PinMediaSchema = z
  .discriminatedUnion('media_type', [
    PinMediaWithImageSchema,
    PinMediaWithVideoSchema,
    PinMediaWithImagesSchema,
    PinMediaWithVideosSchema,
    PinMediaWithImageAndVideoSchema,
  ])
  .openapi({
    description: 'Pin media that can be an image, video, or a mix of both.',
    discriminator: {
      propertyName: 'media_type',
      mapping: {
        image: '#/components/schemas/PinMediaWithImage',
        video: '#/components/schemas/PinMediaWithVideo',
        multiple_images: '#/components/schemas/PinMediaWithImages',
        multiple_videos: '#/components/schemas/PinMediaWithVideos',
        multiple_mixed: '#/components/schemas/PinMediaWithImageAndVideo',
      },
    },
    title: 'Pin media response object.',
  })
  .openapi('PinMedia')

const PinBaseSchema = z
  .object({
    ai_disclosures: AiDisclosuresSchema.exactOptional().openapi({
      description: 'AI disclosure declarations the creator has made about this Pin.',
    }),
    board_id: z
      .string()
      .regex(/^\d+$/)
      .exactOptional()
      .openapi({ description: 'The board to which this Pin belongs.' }),
    board_owner: BoardOwnerSchema.exactOptional().openapi({ readOnly: true }),
    board_section_id: z
      .string()
      .regex(/^\d+$/)
      .nullable()
      .exactOptional()
      .openapi({ description: 'The board section to which this Pin belongs.' }),
    created_at: z.iso.datetime({ offset: true }).exactOptional().openapi({ readOnly: true }),
    creative_type: CreativeTypeSchema.nullable().exactOptional().openapi({ readOnly: true }),
    dominant_color: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Dominant pin color. Hex number, e.g. `#6E7874`.' }),
    has_been_promoted: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether the Pin has been promoted or not.', readOnly: true }),
    id: z.string().regex(/^\d+$/),
    is_owner: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Whether the "operation user_account" is the Pin owner.',
        readOnly: true,
      }),
    is_product: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether the Pin is a product Pin.', readOnly: true }),
    is_standard: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether the Pin is standard or not. See documentation on [Changes to Pin creation](/docs/api-features/content-overview/) for more information.',
        readOnly: true,
      }),
    media: PinMediaSchema.exactOptional().openapi({ readOnly: true }),
    parent_pin_id: z
      .string()
      .regex(/^\d+$/)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The source pin id if this pin was saved from another pin. [Learn more](https://help.pinterest.com/article/save-pins-on-pinterest).',
      }),
    pin_metrics: z
      .looseObject({})
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Pin metrics with associated time intervals if any.',
        example: {
          '90d': { pin_click: 7, impression: 2, clickthrough: 3 },
          lifetime_metrics: {
            pin_click: 7,
            impression: 2,
            clickthrough: 3,
            reaction: 10,
            comment: 2,
          },
        },
        readOnly: true,
      }),
  })
  .openapi({ required: ['id'] })
  .openapi('PinBase')

const PinSchema = PinBaseSchema.and(
  z
    .object({
      alt_text: z.string().max(500).nullable().exactOptional(),
      description: z.string().max(800).nullable().exactOptional(),
      link: z.string().max(2048).nullable().exactOptional(),
      title: z.string().max(100).nullable().exactOptional(),
    })
    .openapi({ required: [] }),
)
  .openapi({ description: 'Pin model containing properties related to a Pinterest Pin.' })
  .openapi('Pin')

