const CatalogsHotelMainImageSchema = z
  .object({
    link: z
      .string()
      .exactOptional()
      .openapi({
        description:
          '<= 2000 characters. The link to the main hotel image. Image should be at least 75x75 pixels to avoid errors. Must start with http:// or https://.',
      }),
    tag: z
      .array(z.string())
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Tag appended to the image that identifies image category or details. There can be multiple tags associated with an image',
      }),
  })
  .openapi({ description: 'The main hotel image', required: [] })
  .openapi('CatalogsHotelMainImage')

const CatalogsHotelAttributesSchema = CatalogsUpdatableHotelAttributesSchema.and(
  z
    .object({
      additional_image_link: z
        .array(z.string())
        .nullable()
        .exactOptional()
        .openapi({
          description:
            '<= 2000 characters. The links to additional images for your hotel. Up to ten additional images can be used to show a hotel from different angles. Must begin with http:// or https://.',
          example: [
            'https://scene.example.com/image/image_v2.jpg',
            'https://scene.example.com/image/image_v3.jpg',
          ],
        }),
      ai_disclosures: z
        .array(CatalogsAiContentDisclosureSchema)
        .exactOptional()
        .openapi({
          description:
            'AI content disclosures for individual assets (main_image.link or additional_image_link) on this hotel item. Each entry declares which disclosure types apply to a single asset URL.',
          example: [
            { url: 'https://scene.example.com/image/image_v3.jpg', disclosure: ['ai_modified'] },
          ],
        }),
      main_image: CatalogsHotelMainImageSchema.exactOptional().openapi({
        description: 'The main hotel image',
      }),
    })
    .openapi({ required: [] }),
).openapi('CatalogsHotelAttributes')

