const AdsAnalyticsCreateAsyncRequestSchema = z
  .object({
    ad_group_ids: z
      .array(PinterestLibIntegerFormatTypeSchema)
      .min(1)
      .max(500)
      .exactOptional()
      .openapi({ description: 'List of ad group ids' }),
    ad_group_statuses: z
      .array(AdGroupSummaryStatusSchema)
      .min(1)
      .max(6)
      .exactOptional()
      .openapi({ description: 'List of values for filtering' }),
    ad_ids: z
      .array(PinterestLibIntegerFormatTypeSchema)
      .min(1)
      .max(500)
      .exactOptional()
      .openapi({
        description:
          'List of ad ids. This parameter is not supported for Product Item level reports.',
      }),
    ad_statuses: z
      .array(PinPromotionSummaryStatusSchema)
      .min(1)
      .max(6)
      .exactOptional()
      .openapi({
        description:
          'List of values for filtering. This parameter is not supported for Product Item level reports.',
      }),
    attribution_types: z
      .array(ConversionReportAttributionTypeSchema)
      .exactOptional()
      .openapi({ description: 'List of attribution types for the conversion report.' }),
    campaign_brand_label: z
      .string()
      .exactOptional()
      .openapi({ description: 'Campaign brand label for filtering.' }),
    campaign_custom_label: z
      .string()
      .exactOptional()
      .openapi({ description: 'Campaign custom label for filtering.' }),
    campaign_ids: z
      .array(PinterestLibIntegerFormatTypeSchema)
      .min(1)
      .max(500)
      .exactOptional()
      .openapi({ description: 'List of campaign ids' }),
    campaign_objective_types: z
      .array(z.any())
      .min(1)
      .max(7)
      .exactOptional()
      .openapi({ description: 'List of values for filtering. ["WEB_SESSIONS"] is in BETA.' }),
    campaign_statuses: z
      .array(CampaignSummaryStatusSchema)
      .min(1)
      .max(6)
      .exactOptional()
      .openapi({ description: 'List of status values for filtering' }),
    click_window_days: ConversionAttributionWindowDaysSchema.default(30)
      .exactOptional()
      .openapi({
        description:
          'Number of days to use as the conversion attribution window for a pin click action.',
      }),
    columns: z
      .array(ReportingColumnAsyncSchema)
      .exactOptional()
      .openapi({
        description:
          'Metric and entity columns. Pin promotion and ad related columns are not supported for Product Item level reports.',
      }),
    combine_targeting_types: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Determines if the targeting types included in the request should be consolidated into a single breakdown.',
      }),
    conversion_report_time: ConversionReportTimeTypeSchema.default('TIME_OF_AD_ACTION')
      .exactOptional()
      .openapi({ description: 'Date dimension for conversion metrics.' }),
    custom_conversion_event_metrics: z
      .array(CustomConversionEventMetricsSchema)
      .exactOptional()
      .openapi({
        description:
          'List of advertiser-defined custom conversion event metrics to include in the report',
      }),
    end_date: z
      .string()
      .regex(/^\d{4}-\d{2}-\d{2}$/)
      .openapi({ description: 'Metric report end date (UTC). Format: YYYY-MM-DD' }),
    end_hour: z
      .int()
      .min(0)
      .max(23)
      .exactOptional()
      .openapi({
        description:
          'Which hour of the end date to stop the report (inclusive). Only allowed for hourly reports.',
      }),
    engagement_window_days: ConversionAttributionWindowDaysSchema.default(30)
      .exactOptional()
      .openapi({
        description:
          'Number of days to use as the conversion attribution window for an engagement action.',
      }),
    granularity: GranularitySchema.openapi({
      description:
        '  TOTAL - metrics are aggregated over the specified date range.\n  DAY - metrics are broken down daily.\n  HOUR - metrics are broken down hourly.\n  WEEKLY - metrics are broken down weekly.\n  MONTHLY - metrics are broken down monthly.',
    }),
    level: MetricsReportingLevelSchema.exactOptional().openapi({
      description: 'Level of the report',
    }),
    metrics_filters: z
      .array(AdsAnalyticsMetricsFilterSchema)
      .min(1)
      .exactOptional()
      .openapi({ description: 'List of metrics filters' }),
    primary_sort: PrimarySortSchema.default('BY_ID').exactOptional(),
    product_group_ids: z
      .array(PinterestLibIntegerFormatTypeSchema)
      .min(1)
      .max(500)
      .exactOptional()
      .openapi({ description: 'List of product group ids' }),
    product_group_statuses: z
      .array(ProductGroupSummaryStatusSchema)
      .min(1)
      .max(6)
      .exactOptional()
      .openapi({ description: 'List of values for filtering' }),
    product_item_ids: z
      .array(PinterestLibIntegerFormatTypeSchema)
      .min(1)
      .max(500)
      .exactOptional()
      .openapi({ description: 'List of product item ids' }),
    report_format: DataOutputFormatSchema.default('JSON').exactOptional(),
    reporting_timezone: ReportingTimeZoneSchema.exactOptional().openapi({
      description: 'Specify the timezone to be applied for the reporting.',
    }),
    start_date: z
      .string()
      .regex(/^\d{4}-\d{2}-\d{2}$/)
      .openapi({ description: 'Metric report start date (UTC). Format: YYYY-MM-DD' }),
    start_hour: z
      .int()
      .min(0)
      .max(23)
      .exactOptional()
      .openapi({
        description:
          'Which hour of the start date to begin the report. Only allowed for hourly reports.',
      }),
    targeting_types: z
      .array(AdAdsAnalyticsAsyncTargetingTypesSchema)
      .min(1)
      .max(5)
      .exactOptional()
      .openapi({
        description:
          'List of targeting types. Requires `level` to be a value ending in `_TARGETING`.',
      }),
    view_window_days: ConversionAttributionWindowDaysSchema.default(1)
      .exactOptional()
      .openapi({
        description:
          'Number of days to use as the conversion attribution window for a view action.',
      }),
  })
  .openapi({ required: ['end_date', 'granularity', 'start_date'] })
  .openapi('AdsAnalyticsCreateAsyncRequest')

