const CatalogsCreativeAssetsBatchItemSchema = z
  .discriminatedUnion('operation', [
    CatalogsCreateCreativeAssetsItemSchema,
    CatalogsUpsertCreativeAssetsItemSchema,
    CatalogsUpdateCreativeAssetsItemSchema,
    CatalogsDeleteCreativeAssetsItemSchema,
  ])
  .openapi({
    description: 'Creative assets batch item',
    discriminator: {
      propertyName: 'operation',
      mapping: {
        CREATE: '#/components/schemas/CatalogsCreateCreativeAssetsItem',
        UPSERT: '#/components/schemas/CatalogsUpsertCreativeAssetsItem',
        UPDATE: '#/components/schemas/CatalogsUpdateCreativeAssetsItem',
        DELETE: '#/components/schemas/CatalogsDeleteCreativeAssetsItem',
      },
    },
  })
  .openapi('CatalogsCreativeAssetsBatchItem')

const CatalogsCreativeAssetsBatchRequestSchema = z
  .object({
    catalog_id: PinterestLibIntegerFormatTypeSchema.exactOptional().openapi({
      description:
        'Catalog id pertaining to the creative assets item. If not provided, default to oldest creative assets catalog',
      example: '2680059592705',
    }),
    catalog_type: z.literal('CREATIVE_ASSETS'),
    country: CountrySchema,
    items: z
      .array(CatalogsCreativeAssetsBatchItemSchema)
      .min(1)
      .max(1000)
      .openapi({ description: 'Array with creative assets item operations' }),
    language: z
      .union([CatalogsLocaleSchema, LanguageSchema])
      .openapi({ description: 'We recommend using the CatalogsLocale values.' }),
  })
  .openapi({
    description: 'Request object to update catalogs creative assets items',
    required: ['catalog_type', 'country', 'items', 'language'],
  })
  .openapi('CatalogsCreativeAssetsBatchRequest')

const CatalogsFeedCredentialsSchema = z
