const CatalogsFeedProcessingScheduleSchema = z
  .object({
    time: z
      .string()
      .regex(/^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]$/)
      .openapi({ description: 'A time in format HH:MM with leading 0 (zero)' }),
    timezone: CatalogsFeedProcessingScheduleTimezoneSchema.openapi({
      description: 'The timezone considered for the processing schedule time.',
    }),
  })
  .nullable()
  .openapi({
    description:
      'Daily processing schedule. This field is **OPTIONAL**. Use this to configure the preferred time for processing a feed (otherwise random).',
    required: ['time', 'timezone'],
    title: 'catalogs_processing_schedule',
  })
  .openapi('CatalogsFeedProcessingSchedule')

const CatalogsStatusSchema = z
  .enum(['ACTIVE', 'INACTIVE'])
  .openapi({
    description:
      'Status for catalogs entities. Present in catalogs_feed values. When a feed is deleted, the response will inform DELETED as status.',
  })
  .openapi('CatalogsStatus')

const CatalogsCreativeAssetsFeedSchema = z
  .object({
    catalog_id: z
      .string()
      .regex(/^\d+$/)
      .openapi({
        description:
          'Catalog id pertaining to the feed. If not provided, feed will use a default catalog based on type.',
      }),
    catalog_type: z.literal('CREATIVE_ASSETS'),
    created_at: z.iso.datetime({ offset: true }).openapi({ readOnly: true }),
    credentials: CatalogsFeedCredentialsSchema.exactOptional(),
    default_country: CountrySchema,
    default_currency: NullableCurrencySchema.exactOptional(),
    default_locale: z
      .string()
      .openapi({ description: 'The locale used within a feed for product descriptions.' }),
    format: CatalogsFormatSchema,
    id: z
      .string()
      .regex(/^\d+$/)
      .openapi({
        description: 'ID of the feed entity.',
        example: '864344156814050986',
        readOnly: true,
      }),
    location: z
      .string()
      .regex(/^(http|https|ftp|sftp):\/\//)
      .openapi({
        description:
          'The URL where a feed is available for download. This URL is what Pinterest will use to download a feed for processing.',
      }),
    name: z
      .string()
      .nullable()
      .openapi({
        description:
          'A human-friendly name associated to a given feed. This value is currently nullable due to historical reasons. It is expected to become non-nullable in the future.',
      }),
    preferred_processing_schedule: CatalogsFeedProcessingScheduleSchema.exactOptional(),
    status: CatalogsStatusSchema,
    updated_at: z.iso.datetime({ offset: true }).openapi({ readOnly: true }),
  })
  .openapi({
    description: 'Catalogs Creative Asset Feed object',
    required: [
      'id',
      'default_locale',
      'location',
      'name',
      'created_at',
      'updated_at',
      'format',
      'status',
      'catalog_type',
      'catalog_id',
      'default_country',
    ],
    title: 'catalogs_creative_assets_feed',
  })
  .openapi('CatalogsCreativeAssetsFeed')

const DeprecatedCatalogFeedsCreateRequestDefaultLocaleSchema = z
  .string()
  .openapi({
    description:
      'The locale used within a feed for product descriptions. This free text string version is deprecated in favor of official list of supported locales defined by CatalogsLocale.',
    deprecated: true,
  })
  .openapi('DeprecatedCatalogFeedsCreateRequestDefaultLocale')

const FeedLocationSchema = z
  .string()
  .regex(/^(http|https|ftp|sftp):\/\//)
  .openapi({
    description:
      'The URL where a feed is available for download. This URL is what Pinterest will use to download a feed for processing.',
  })
  .openapi('FeedLocation')

const FeedDisplayNameSchema = z
  .string()
  .openapi({ description: 'A human-friendly name associated to a given feed.' })
  .openapi('FeedDisplayName')

const CatalogsCreativeAssetsFeedsCreateRequestSchema = z
  .strictObject({
    catalog_id: z
      .string()
      .regex(/^\d+$/)
      .exactOptional()
      .openapi({
        description:
          'Catalog id pertaining to the feed. If not provided, feed will use a default catalog based on type.',
      }),
    catalog_type: z.literal('CREATIVE_ASSETS'),
    credentials: CatalogsFeedCredentialsSchema.exactOptional(),
    default_country: CountrySchema,
    default_currency: NullableCurrencySchema.exactOptional(),
    default_locale: z
      .union([CatalogsLocaleSchema, DeprecatedCatalogFeedsCreateRequestDefaultLocaleSchema])
      .openapi({ description: 'The locale used within a feed for product descriptions.' }),
    format: CatalogsFormatSchema,
    location: FeedLocationSchema,
    name: FeedDisplayNameSchema,
    preferred_processing_schedule: CatalogsFeedProcessingScheduleSchema.exactOptional(),
    status: CatalogsStatusSchema.default('ACTIVE').exactOptional(),
  })
  .openapi({
    description: 'Request object for creating a feed.',
    required: ['default_locale', 'format', 'location', 'name', 'catalog_type', 'default_country'],
    title: 'feeds_creative_assets_create_request',
  })
  .openapi('CatalogsCreativeAssetsFeedsCreateRequest')

const CatalogsCreativeAssetsFeedsUpdateRequestSchema = z
  .strictObject({
    catalog_type: z.literal('CREATIVE_ASSETS'),
    credentials: CatalogsFeedCredentialsSchema.exactOptional(),
    default_currency: NullableCurrencySchema.exactOptional(),
    format: CatalogsFormatSchema.exactOptional(),
    location: FeedLocationSchema.exactOptional(),
    name: FeedDisplayNameSchema.exactOptional(),
    preferred_processing_schedule: CatalogsFeedProcessingScheduleSchema.exactOptional(),
    status: CatalogsStatusSchema.exactOptional(),
  })
  .openapi({
    description: 'Request object for updating a feed.',
    required: ['catalog_type'],
    title: 'catalogs_feeds_update_request',
  })
  .openapi('CatalogsCreativeAssetsFeedsUpdateRequest')

const ItemProcessingStatusSchema = z
  .enum(['SUCCESS', 'FAILURE', 'PROCESSING'])
  .openapi({ description: 'The status of the item processing record', example: 'SUCCESS' })
  .openapi('ItemProcessingStatus')

const CreativeAssetsProcessingRecordSchema = z
  .object({
    creative_assets_id: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The catalog creative assets id in the merchant namespace',
        example: 'DS0294-M',
      }),
    errors: z
      .array(ItemValidationEventSchema)
      .exactOptional()
      .openapi({
        description:
          'Array with the validation errors for the item processing record. A non empty errors list causes the item processing to fail.',
      }),
    status: ItemProcessingStatusSchema.exactOptional(),
    warnings: z
      .array(ItemValidationEventSchema)
      .exactOptional()
      .openapi({
        description: 'Array with the validation warnings for the item processing record',
      }),
  })
  .openapi({ description: 'Object describing an item processing record', required: [] })
  .openapi('CreativeAssetsProcessingRecord')

const CatalogsCreativeAssetsItemsBatchSchema = z
  .object({
    batch_id: PinterestLibIntegerFormatTypeSchema.exactOptional().openapi({
      description: 'Id of the catalogs items batch',
      example: '595953100599279259',
    }),
    catalog_type: z.literal('CREATIVE_ASSETS'),
    completed_time: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description: "Date and time (UTC) of the batch completion: YYYY-MM-DD'T'hh:mm:ss",
        example: '2024-01-01T20:20:00Z',
      }),
    created_time: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: "Date and time (UTC) of the batch creation: YYYY-MM-DD'T'hh:mm:ss",
        example: '2024-01-01T20:10:40Z',
      }),
    items: z
      .array(CreativeAssetsProcessingRecordSchema)
      .exactOptional()
      .openapi({
        description:
          'Array with the catalogs items processing records part of the catalogs items batch',
      }),
    status: BatchOperationStatusSchema.exactOptional(),
  })
  .openapi({
    description: 'Object describing the catalogs creative assets items batch',
    required: ['catalog_type'],
  })
  .openapi('CatalogsCreativeAssetsItemsBatch')

const CatalogsCreativeAssetsItemsPostFilterSchema = z
  .object({
    catalog_id: z
      .string()
      .regex(/^\d+$/)
      .exactOptional()
      .openapi({
        description:
          'Catalog id pertaining to the creative assets item. If not provided, default to oldest creative assets catalog',
      }),
    catalog_type: z.literal('CREATIVE_ASSETS'),
    creative_assets_ids: z.array(z.string()).min(1).max(1000),
  })
  .openapi({ required: ['catalog_type', 'creative_assets_ids'] })
  .openapi('CatalogsCreativeAssetsItemsPostFilter')

const CatalogsCreativeAssetsListProductsByCatalogBasedFilterRequestSchema = z
  .strictObject({
    catalog_id: PinterestLibIntegerFormatTypeSchema.openapi({
      description: 'Catalog ID pertaining to the product group.',
      example: '2680059592705',
    }),
    catalog_type: z.literal('CREATIVE_ASSETS'),
    filters: CatalogsCreativeAssetsProductGroupFiltersSchema,
  })
  .openapi({
    description:
      'Request object to list products for a given creative assets catalog_id and product group filter.',
    required: ['catalog_id', 'catalog_type', 'filters'],
    title: 'creative_assets_list_products_by_catalog_based_filter_request',
  })
  .openapi('CatalogsCreativeAssetsListProductsByCatalogBasedFilterRequest')

const CreativeAssetsVisibilityTypeSchema = z
  .enum(['VISIBLE', 'HIDDEN'])
  .openapi({ description: 'Creative assets visibility.' })
  .openapi('CreativeAssetsVisibilityType')

const CatalogsCreativeAssetsProductMetadataSchema = z
  .object({
    creative_assets_id: z
      .string()
      .openapi({
        description: 'The user-created unique ID that represents the creative assets item.',
        example: '123abc',
      }),
    visibility: CreativeAssetsVisibilityTypeSchema,
  })
  .openapi({
    description: 'Creative assets product metadata entity',
    required: ['creative_assets_id', 'visibility'],
  })
  .openapi('CatalogsCreativeAssetsProductMetadata')

const CatalogsCreativeAssetsProductSchema = z
  .object({
    catalog_type: z.literal('CREATIVE_ASSETS'),
    metadata: CatalogsCreativeAssetsProductMetadataSchema,
    pin: PinSchema,
  })
  .openapi({ required: ['catalog_type', 'metadata', 'pin'] })
  .openapi('CatalogsCreativeAssetsProduct')

const CatalogsCreativeAssetsProductGroupSchema = z
  .object({
    catalog_id: PinterestLibIntegerFormatTypeSchema.openapi({
      description: 'Catalog ID pertaining to the product group.',
      example: '2680059592705',
    }),
    catalog_type: z.literal('CREATIVE_ASSETS'),
    created_at: z
      .int()
      .exactOptional()
      .openapi({
        description: 'Unix timestamp in seconds of when catalog product group was created.',
        example: 1621350033000,
      }),
    description: z.string().nullable().exactOptional(),
    filters: CatalogsCreativeAssetsProductGroupFiltersSchema,
    id: PinterestLibIntegerFormatTypeSchema.openapi({
      description: 'ID of the catalog product group.',
      example: '443727193917',
    }),
    name: z
      .string()
      .exactOptional()
      .openapi({ description: 'Name of catalog product group', example: 'Most Popular' }),
    updated_at: z
      .int()
      .exactOptional()
      .openapi({
        description: 'Unix timestamp in seconds of last time catalog product group was updated.',
        example: 1622742155000,
      }),
  })
  .openapi({
    required: ['catalog_id', 'id', 'catalog_type', 'filters'],
    title: 'creative_assets_product_group',
  })
  .openapi('CatalogsCreativeAssetsProductGroup')

