const CatalogsDeleteRetailItemSchema = z
  .object({
    item_id: z
      .string()
      .openapi({
        description: 'The catalog item id in the merchant namespace',
        example: 'DS0294-M',
      }),
    last_updated_time: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The millisecond timestamp when the item was lastly modified by the merchant.',
        example: 1641483432072,
      }),
    operation: z.literal('DELETE'),
  })
  .openapi({ description: 'An item to be deleted', required: ['item_id', 'operation'] })
  .openapi('CatalogsDeleteRetailItem')

