const CatalogsItemValidationIssuesSchema = z
  .object({
    errors: CatalogsItemValidationErrorsSchema,
    item_id: z
      .string()
      .nullable()
      .openapi({
        description: 'The merchant-created unique ID that represents the product.',
        example: 'DS0294-L',
      }),
    item_number: z
      .int()
      .openapi({
        description:
          "Item number based on order of appearance in the Catalogs Feed. For example, '0' refers to first item found in a feed that was downloaded from a 'location' specified during feed creation.",
        example: 0,
      }),
    warnings: CatalogsItemValidationWarningsSchema,
  })
  .openapi({ required: ['item_id', 'item_number', 'warnings', 'errors'] })
  .openapi('CatalogsItemValidationIssues')

const ItemProcessingRecordSchema = z
  .object({
    errors: z
      .array(ItemValidationEventSchema)
      .exactOptional()
      .openapi({
        description:
          'Array with the validation errors for the item processing record. A non empty errors list causes the item processing to fail.',
      }),
    item_id: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The catalog item id in the merchant namespace',
        example: 'DS0294-M',
      }),
    status: ItemProcessingStatusSchema.exactOptional(),
    warnings: z
      .array(ItemValidationEventSchema)
      .exactOptional()
      .openapi({
        description: 'Array with the validation warnings for the item processing record',
      }),
  })
  .openapi({ description: 'Object describing an item processing record', required: [] })
  .openapi('ItemProcessingRecord')

const CatalogsRetailItemsBatchSchema = z
  .object({
    batch_id: PinterestLibIntegerFormatTypeSchema.exactOptional().openapi({
      description: 'Id of the catalogs items batch',
      example: '595953100599279259',
    }),
    catalog_type: z.literal('RETAIL'),
    completed_time: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description: "Date and time (UTC) of the batch completion: YYYY-MM-DD'T'hh:mm:ss",
        example: '2024-01-01T20:20:00Z',
      }),
    created_time: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description:
          "Date and time (UTC) of the batch creation: YYYY-MM-DD'T'hh:mm:ss. If null, batch creation was skipped due to a recent duplicate ingestion.",
        example: '2024-01-01T20:10:40Z',
      }),
    items: z
      .array(ItemProcessingRecordSchema)
      .exactOptional()
      .openapi({
        description:
          'Array with the catalogs items processing records part of the catalogs items batch',
      }),
    status: BatchOperationStatusSchema.exactOptional(),
  })
  .openapi({
    description: 'Object describing the catalogs retail items batch',
    required: ['catalog_type', 'created_time'],
  })
  .openapi('CatalogsRetailItemsBatch')

const CatalogsItemsBatchSchema = z
  .discriminatedUnion('catalog_type', [
    CatalogsRetailItemsBatchSchema,
    CatalogsHotelItemsBatchSchema,
    CatalogsCreativeAssetsItemsBatchSchema,
  ])
  .openapi({
    description: 'Object describing the catalogs items batch',
    discriminator: {
      propertyName: 'catalog_type',
      mapping: {
        RETAIL: '#/components/schemas/CatalogsRetailItemsBatch',
        HOTEL: '#/components/schemas/CatalogsHotelItemsBatch',
        CREATIVE_ASSETS: '#/components/schemas/CatalogsCreativeAssetsItemsBatch',
      },
    },
  })
  .openapi('CatalogsItemsBatch')

