const ConversionProductReportGranularitySchema = z
  .enum(['TOTAL', 'WEEK', 'MONTH'])
  .openapi({
    description:
      'Report granularity for time-based aggregation:\n- TOTAL: Metrics are aggregated over the specified date range\n- WEEK: Metrics are broken down weekly\n- MONTH: Metrics are broken down monthly',
  })
  .openapi('ConversionProductReportGranularity')

const ConversionProductReportLevelSchema = z
  .enum(['ADVERTISER', 'CAMPAIGN', 'AD_GROUP'])
  .openapi({ description: 'Level of the report' })
  .openapi('ConversionProductReportLevel')

const PinterestLibAlphaNumericFormatTypeSchema = z
  .string()
  .regex(/^[a-zA-Z0-9]+$/)
  .openapi('PinterestLibAlphaNumericFormatType')

const ConversionProductReportCreateSchema = z
  .object({
    ad_group_ids: z
      .array(PinterestLibIntegerFormatTypeSchema)
      .min(1)
      .max(500)
      .exactOptional()
      .openapi({
        description:
          '  List of ad group ids.\n  Only support ad_group_ids field when level of the report is AD_GROUP.',
        example: ['12345678'],
      }),
    campaign_ids: z
      .array(PinterestLibIntegerFormatTypeSchema)
      .min(1)
      .max(500)
      .exactOptional()
      .openapi({
        description:
          '  List of campaign ids.\n  Only support campaign_ids field when level of the report is CAMPAIGN.',
        example: ['12345678'],
      }),
    campaign_objective_types: z
      .array(ConversionObjectiveTypeSchema)
      .min(1)
      .max(7)
      .exactOptional()
      .openapi({
        description:
          "List of values for filtering. Default is ['CONSIDERATION','AWARENESS','WEB_CONVERSION','VIDEO_COMPLETION'].",
      }),
    click_window_days: ConversionAttributionWindowDaysSchema.default(30)
      .exactOptional()
      .openapi({
        description:
          'Number of days to use as the conversion attribution window for a pin click action. Applies to Pinterest Tag conversion metrics. Prior conversion tags use their defined attribution windows. If not specified, defaults to `30` days.',
      }),
    columns: z
      .array(ConversionProductReportingColumnSchema)
      .openapi({ description: 'Metric and entity columns' }),
    conversion_product_attribution_type: ConversionProductAttributionTypeSchema.default('DEFAULT')
      .exactOptional()
      .openapi({
        description:
          '  Required attribution type of the B/C/S report.\n  When the attribution type is BRAND_ATTRIBUTION, start_date for the report must be after 2025-04-01.',
      }),
    conversion_product_breakdown: ConversionProductReportBreakdownTypeSchema.default(
      'PRODUCT_BRAND',
    )
      .exactOptional()
      .openapi({
        description:
          'Report breakdown type. This is used to specify the breakdown of the report by brand, category, or SKU.',
      }),
    conversion_report_time: ConversionReportTimeTypeSchema.default('TIME_OF_AD_ACTION')
      .exactOptional()
      .openapi({
        description:
          'The date by which the conversion metrics returned from this endpoint will be reported. There are two dates associated with a conversion event: the date that the user interacted with the ad, and the date that the user completed a conversion event.',
      }),
    end_date: z
      .string()
      .regex(/^\d{4}-\d{2}-\d{2}$/)
      .openapi({
        description:
          '  Metric report end date (UTC). Format: YYYY-MM-DD.\n  A max of 1 year is allowed between the start and end date for reports.',
        example: '2024-04-23',
      }),
    granularity: ConversionProductReportGranularitySchema.openapi({
      description: 'Report granularity for time-based metric aggregation',
    }),
    level: ConversionProductReportLevelSchema.openapi({ description: 'Level of the report' }),
    product_sku_ids: z
      .array(PinterestLibAlphaNumericFormatTypeSchema)
      .min(2)
      .max(30000)
      .exactOptional()
      .openapi({
        description:
          '  List of SKU ids.\n  Only support product_sku_ids field when report breakdown type is PRODUCT_SKU_GROUP.',
        example: ['WBC45678', 'WBC45679'],
      }),
    report_name: z.string().openapi({ description: 'Name of the conversion product report' }),
    start_date: z
      .string()
      .regex(/^\d{4}-\d{2}-\d{2}$/)
      .openapi({
        description:
          '  Metric report start date (UTC). Format: YYYY-MM-DD.\n  Start date must be after 2024-03-16. 7 day minimum time window for report is required.',
        example: '2024-04-17',
      }),
    view_window_days: ConversionAttributionWindowDaysSchema.default(30)
      .exactOptional()
      .openapi({
        description:
          'Number of days to use as the conversion attribution window for a view action. Applies to Pinterest Tag conversion metrics. Prior conversion tags use their defined attribution windows. If not specified, defaults to `1` day.',
      }),
  })
  .openapi({
    description: 'Resource create operation model.',
    required: ['columns', 'end_date', 'granularity', 'level', 'report_name', 'start_date'],
  })
  .openapi('ConversionProductReportCreate')

