const LocalInventoryItemResponseSchema = z
  .object({
    ad_link: z
      .string()
      .exactOptional()
      .openapi({ description: 'Ad link for the item', example: 'https://examplelink.com' }),
    availability: ItemAvailabilitySchema.exactOptional().openapi({
      description: 'Availability status of the item',
      example: 'in stock',
    }),
    created_at: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The millisecond timestamp when the local inventory item was created',
        example: 1641483432072,
      }),
    item_id: z
      .string()
      .openapi({
        description: 'The catalog item id in the merchant namespace',
        example: 'DS0294-M',
      }),
    last_updated_time: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'The millisecond timestamp when the local inventory item was lastly modified by the merchant.',
        example: 1641483432072,
      }),
    price: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The price of the product. It supports the following formats, "49.99 USD", "49.99USD" and "49.99". If the currency is not included, we default to US dollars.',
        example: '49.99 USD',
      }),
    sale_price: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The sale price of the product. It supports the following formats, "24.99 USD", "24.99USD" and "24.99". If the currency is not included, we default to US dollars.',
        example: '24.99 USD',
      }),
    store_metadata: StoreMetadataSchema.openapi({
      description: 'Store metadata for this local inventory item',
    }),
  })
  .openapi({
    description: 'Local inventory item response',
    required: ['item_id', 'store_metadata', 'created_at', 'last_updated_time'],
  })
  .openapi('LocalInventoryItemResponse')

