const PromotionSchema = z
  .object({
    ad_account_id: z
      .string()
      .regex(/^\d+$/)
      .openapi({
        description: 'The Ad Account ID that this promotion belongs to.',
        readOnly: true,
      }),
    discount_status: DiscountStatusSchema.exactOptional(),
    end_time: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'Promotion end time. Unix timestamp in seconds. Independent of campaign end time.',
      }),
    external_id: z
      .string()
      .max(64)
      .exactOptional()
      .openapi({
        description:
          'Platform-specific ID for this promotion. Will be null for promotions first created within Pinterest.',
      }),
    id: z.string().regex(/^\d+$/).max(18).openapi({ description: 'Promotion ID' }),
    platform_type: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The source integration platform used when creating the promotion. Currently supported values are 'DEFAULT' and 'SHOPIFY'.",
      }),
    promotion_code: z
      .string()
      .exactOptional()
      .openapi({ description: 'Code that can be used to redeem a promotion.' }),
    promotion_custom_id: z
      .string()
      .max(50)
      .exactOptional()
      .openapi({
        description:
          'An optional field for user defined promotion ID for this promotion. Will copy from Pinterest system generated ID if user did not provide one.',
      }),
    promotion_title: z.string().openapi({ description: 'Internal name for the promotion.' }),
    promotion_type: PromotionTypeSchema,
    start_time: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'Promotion start time. Unix timestamp in seconds. Independent of campaign start time.',
      }),
    status: EntityStatusSchema.exactOptional().openapi({ readOnly: true }),
    template_values: z
      .array(PromotionTemplateValueSchema)
      .min(0)
      .max(2)
      .exactOptional()
      .openapi({
        description: 'List of values to be inserted in the promotion type-specific template.',
      }),
  })
  .openapi({ required: ['id', 'ad_account_id', 'promotion_title', 'promotion_type'] })
  .openapi('Promotion')

